<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$pdo=db();$status=(string)($_GET['status']??'');$date=(string)($_GET['date']??'');$search=trim((string)($_GET['q']??''));$sql='SELECT e.*,a.username actor_username,a.full_name actor_name,t.username target_username,t.full_name target_name FROM account_security_events e LEFT JOIN users a ON a.id=e.actor_user_id LEFT JOIN users t ON t.id=e.target_user_id WHERE 1=1';$params=[];if(in_array($status,['success','failed','blocked'],true)){$sql.=' AND e.status=?';$params[]=$status;}if($date){$sql.=' AND DATE(e.created_at)=?';$params[]=$date;}if($search){$sql.=' AND (e.event_type LIKE ? OR a.username LIKE ? OR t.username LIKE ? OR e.details LIKE ?)';$needle='%'.$search.'%';array_push($params,$needle,$needle,$needle,$needle);}$sql.=' ORDER BY e.created_at DESC LIMIT 500';$stmt=$pdo->prepare($sql);$stmt->execute($params);$events=$stmt->fetchAll();$labels=['login'=>'Login akun','logout'=>'Logout akun','password_changed'=>'Password berhasil diganti','password_reset_requested'=>'Permintaan lupa password','daily_report_saved'=>'Laporan harian Guru disimpan','tahsin_score_saved'=>'Nilai Tahsin/Tahfizh disimpan','level_exam_saved'=>'Ujian kenaikan level disimpan','munaqosyah_saved'=>'Munaqosyah disimpan','account_created'=>'Akun dibuat','account_deleted'=>'Akun dihapus','role_changed'=>'Role akun diubah','student_created'=>'Siswa ditambahkan','student_updated'=>'Data siswa diperbarui','students_imported'=>'Excel siswa diimpor'];$pageTitle='Audit Aktivitas';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Keamanan Sistem</p><h1 class="page-title">Audit Aktivitas</h1><p class="page-description">Telusuri pelaku, target, rincian, waktu, dan hasil perubahan sistem.</p></div><span class="badge badge-green">● <?= count($events) ?> aktivitas</span></div><section class="card"><form method="get" class="filter-row"><input class="input" name="q" value="<?= e($search) ?>" placeholder="Cari aktivitas atau username..."><div class="actions"><select class="select" name="status"><option value="">Semua Status</option><?php foreach(['success','failed','blocked'] as $item):?><option <?= $status===$item?'selected':'' ?>><?= $item ?></option><?php endforeach;?></select><input class="input" type="date" name="date" value="<?= e($date) ?>"><button class="btn btn-primary">Filter</button></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Aktivitas</th><th>Pelaku</th><th>Target</th><th>Rincian</th><th>Status</th></tr></thead><tbody><?php foreach($events as $event):$details=json_decode($event['details'],true)?:[];$detailParts=[];foreach($details as $key=>$value){if(is_scalar($value))$detailParts[]=ucwords(str_replace('_',' ',$key)).': '.$value;}?><tr><td><?= e(format_date_id($event['created_at'],true)) ?></td><td class="name"><?= e($labels[$event['event_type']]??ucwords(str_replace('_',' ',$event['event_type']))) ?></td><td><?= e($event['actor_username']??'Sistem/Tamu') ?><br><small class="muted"><?= e($event['actor_name']??'') ?></small></td><td><?= e($event['target_username']??($details['student']??$details['target']??'-')) ?><br><small class="muted"><?= e($event['target_name']??'') ?></small></td><td><?= e(implode(' · ',$detailParts)?:'Tidak ada rincian tambahan') ?></td><td><span class="badge <?= $event['status']==='success'?'badge-green':($event['status']==='blocked'?'badge-yellow':'badge-red') ?>"><?= e($event['status']==='success'?'Berhasil':($event['status']==='blocked'?'Diblokir':'Gagal')) ?></span></td></tr><?php endforeach;?><?php if(!$events):?><tr><td colspan="6"><div class="empty"><strong>Tidak ada aktivitas sesuai filter</strong>Coba ubah pencarian, tanggal, atau status.</div></td></tr><?php endif;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

